const items = $input.all();
const sourceItems = $('Парсер последней доработки').all();

function toNumber(value) {
  if (value === null || value === undefined || value === '') {
    return 0;
  }

  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : 0;
  }

  const normalized = String(value)
    .replace(',', '.')
    .trim();

  const match = normalized.match(/\d+(?:\.\d+)?/);

  if (!match) {
    return 0;
  }

  const num = Number(match[0]);

  return Number.isFinite(num) ? num : 0;
}

return items.map((item, index) => {
  const source = sourceItems[index]?.json ?? {};

  let raw =
    item.json.output?.[0]?.content?.[0]?.text ??
    item.json.output_text ??
    item.json.text ??
    '';

  raw = String(raw)
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  let review = {};

  try {
    review = JSON.parse(raw);
  } catch (error) {
    review = {
      Hook_балл: 0,
      Конфликт_балл: 0,
      Сценарий_балл: 0,
      Медицина_балл: 0,
      Визуал_CTA_балл: 0,
      Балл: 0,
      Оценка: '0/10',
      Проблемы: 'Ошибка разбора финальной оценки',
      Улучшение: '',
      Решение: 'Ручная проверка',
      Статус: 'Требует ручной проверки'
    };
  }

  const hookScore = toNumber(review.Hook_балл);
  const conflictScore = toNumber(review.Конфликт_балл);
  const scriptScore = toNumber(review.Сценарий_балл);
  const medicineScore = toNumber(review.Медицина_балл);
  const visualCtaScore = toNumber(review.Визуал_CTA_балл);

  let score = toNumber(review.Балл);

  if (score === 0) {
    score = toNumber(review.Оценка);
  }

  const hasAllCriteria =
    hookScore > 0 &&
    conflictScore > 0 &&
    scriptScore > 0 &&
    medicineScore > 0 &&
    visualCtaScore > 0;

  const criteriaPassed =
    hasAllCriteria &&
    hookScore >= 8 &&
    conflictScore >= 8 &&
    scriptScore >= 8 &&
    medicineScore >= 8 &&
    visualCtaScore >= 8;

  const finalStatus =
    criteriaPassed
      ? 'Готово'
      : 'Требует ручной проверки';

  const finalDecision =
    criteriaPassed
      ? 'Принять'
      : 'Ручная проверка';

  return {
    json: {
      ...source,

      Hook_балл: hookScore,
      Конфликт_балл: conflictScore,
      Сценарий_балл: scriptScore,
      Медицина_балл: medicineScore,
      Визуал_CTA_балл: visualCtaScore,

      Оценка:
        review.Оценка ??
        `${score}/10`,

      Балл: score,

      Проблемы:
        review.Проблемы ?? '',

      Улучшение:
        review.Улучшение ?? '',

      Решение:
        review.Решение ??
        finalDecision,

      Статус:
        review.Статус === 'Готово' && criteriaPassed
          ? 'Готово'
          : finalStatus
    }
  };
});

