// Находит нужную строку по row_number или ID
function findCurrentItem(items, current) {
  if (!Array.isArray(items) || items.length === 0) {
    return {};
  }

  const currentRow = String(
    current.row_number ?? ""
  );

  const currentId = String(
    current.ID ?? current.Id ?? current.id ?? ""
  );

  const found = items.find(({ json }) => {
    const data = normalize(json);

    const sameRow =
      currentRow &&
      String(data.row_number ?? "") === currentRow;

    const itemId = String(
      data.ID ?? data.Id ?? data.id ?? ""
    );

    const sameId =
      currentId &&
      itemId === currentId;

    return sameRow || sameId;
  });

  return found?.json ?? items[0]?.json ?? {};
}

// Исходные данные Google Sheets
let originalRaw = {};

try {
  originalRaw = findCurrentItem(
    $("Get row(s) in sheet").all(),
    updatedRaw
  );
} catch (error) {
  originalRaw = {};
}

// Данные перед обновлением строки
let mergedRaw = {};

try {
  mergedRaw = findCurrentItem(
    $("Merge Все результаты").all(),
    updatedRaw
  );
} catch (error) {
  mergedRaw = {};
}

// Собираем все данные в один объект
const item = {
  ...normalize(originalRaw),
  ...normalize(mergedRaw),
  ...normalize(updatedRaw)
};

// Возвращает первое непустое значение
function firstValue(...values) {
  return values.find(
    value =>
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
  );
}

// Нормализуем названия отдельных оценок
item["Hook_балл"] = firstValue(
  item["Hook_балл"],
  item["Hook балл"],
  item["Оценка Hook"],
  item["hook_score"]
);

item["Конфликт_балл"] = firstValue(
  item["Конфликт_балл"],
  item["Конфликт балл"],
  item["Оценка Конфликт"],
  item["conflict_score"]
);

item["Сценарий_балл"] = firstValue(
  item["Сценарий_балл"],
  item["Сценарий балл"],
  item["Оценка Сценарий"],
  item["script_score"]
);

item["Медицина_балл"] = firstValue(
  item["Медицина_балл"],
  item["Медицина балл"],
  item["Оценка Медицина"],
  item["medicine_score"]
);

item["Визуал_CTA_балл"] = firstValue(
  item["Визуал_CTA_балл"],
  item["Визуал CTA балл"],
  item["Оценка Визуал CTA"],
  item["visual_cta_score"]
);

// Преобразуем "8.4/10" в 8.4
const scoreText = String(
  firstValue(
    item["Общая оценка"],
    item["Общая_оценка"],
    item["Оценка"],
    "0"
  )
);

const score =
  parseFloat(scoreText.replace(",", ".")) || 0;

const originalDecision = String(
  item["Решение"] ?? ""
).trim();

const accepted =
  score >= 8 &&
  originalDecision.toLowerCase() === "принять";

item["Статус"] = accepted
  ? "Готово"
  : "Требует ручной проверки";

item["Решение"] = accepted
  ? "Принять"
  : "Ручная проверка";

item["Заголовок Telegram"] = accepted
  ? "✅ СЦЕНАРИЙ REELS ГОТОВ"
  : "⚠️ СЦЕНАРИЙ ТРЕБУЕТ РУЧНОЙ ПРОВЕРКИ";

item["Оценка числом"] = score;

return [
  {
    json: item
  }
];

const source = $input.first();
const message = source.json.message ?? {};
const document = message.document ?? null;
const video = message.video ?? null;

const documentIsVideo = Boolean(
  document &&
  String(document.mime_type ?? '').toLowerCase().startsWith('video/')
);

const media = video ?? (documentIsVideo ? document : null);
const caption = String(message.caption ?? message.text ?? '').trim();
const idMatch = caption.match(/(?:reels?\s*)?#?(\d+)/i) ?? caption.match(/\d+/);
const rowId = idMatch?.[1] ?? idMatch?.[0] ?? '';
const fileSize = Number(media?.file_size ?? 0);
const maxSize = 20 * 1024 * 1024;

let errorMessage = '';

if (!media) {
  errorMessage = '⚠️ Отправьте исходное видео как видео или файл. В подписи укажите ID строки, например: 43';
} else if (!rowId) {
  errorMessage = '⚠️ Не найден ID сценария. Отправьте видео с подписью: 43 или reels 43';
} else if (fileSize > maxSize) {
  const sizeMb = (fileSize / 1024 / 1024).toFixed(1);
  errorMessage = `⚠️ Видео весит ${sizeMb} МБ. Telegram-бот может скачать не больше 20 МБ. Сожмите видео и отправьте снова.`;
}

return [{
  json: {
    ...source.json,
    valid_text: errorMessage ? 'no' : 'yes',
    error_message: errorMessage,
    chat_id: message.chat?.id ?? '',
    row_id: String(rowId),
    file_id: media?.file_id ?? '',
    file_size: fileSize,
    source_file_name: media?.file_name ?? `source_${rowId || 'video'}.mp4`
  }
}];

function normalize(object = {}) {
  return Object.fromEntries(
    Object.entries(object).map(([key, value]) => [String(key).trim(), value])
  );
}

const row = normalize($input.first().json);
const meta = $('Разобрать видео').first().json;
const downloaded = $('Скачать видео').first();

const id = String(row.ID ?? '');
const status = String(row.Статус ?? '').trim();
const decision = String(row.Решение ?? '').trim();
const found = Boolean(id) && id === String(meta.row_id);
const ready = found && status === 'Готово' && decision === 'Принять';

let errorMessage = '';
if (!found) {
  errorMessage = `⚠️ Сценарий с ID ${meta.row_id} не найден в Google Sheets.`;
} else if (!ready) {
  errorMessage = `⚠️ Сценарий ID ${meta.row_id} пока нельзя монтировать. Статус: ${status || '—'}. Решение: ${decision || '—'}.`;
}

return [{
  json: {
    ...row,
    ...meta,
    ready_text: ready ? 'yes' : 'no',
    error_message: errorMessage,
    ID: id || meta.row_id
  },
  binary: downloaded.binary
}];

const prepared = $('Подготовить сценарий и видео').first();

return [{
  json: {
    ...prepared.json,
    analysis: $input.first().json
  },
  binary: prepared.binary
}];

const prepared = $('Для транскрипции').first().json;
const current = $input.first().json;

let transcript =
  current.text ??
